sp_HomeTopProdutos	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_HomeTopProdutos`(\nIN p_idEmpresa INT,\n    IN p_dataInicio DATETIME,\n    IN p_dataFim    DATETIME\n)\nBEGIN\n    SELECT\n        pr.nome            AS nomeProduto,\n        SUM(pi.quantidade) AS totalVendido,\n        SUM(pi.valorTotal) AS receitaTotal\n    FROM PedidoItem pi\n    JOIN Pedido p   ON p.idPedido   = pi.idPedido\n    JOIN Produto pr ON pr.idProduto = pi.idProduto\n    WHERE p.idEmpresa = p_idEmpresa\n      AND p.dthPedido BETWEEN p_dataInicio AND p_dataFim\n      AND p.statusPedido_id != 5\n    GROUP BY pr.idProduto, pr.nome\n    ORDER BY totalVendido DESC\n    LIMIT 5;\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
